INSERT INTO public.reviews (name, review_text, image_url, rating, display_order) VALUES
('Ayesha from Defense Phase 1', 'Excellent stitching quality! The fit was perfect and delivery was on time. Highly recommended for Pakistani dresses online.', 'https://i.postimg.cc/SYd3RD7D/Whats-App-Image-2025-06-18-at-4-46-42-PM.jpg', 5, 1),
('Fatima from PECHS Block 6', 'Amazing work by MA Tailor! The attention to detail in my shalwar kameez was outstanding. Will definitely order again.', 'https://i.postimg.cc/5QbDfZvX/Whats-App-Image-2025-06-18-at-4-53-32-PM.jpg', 5, 2),
('Sarah from Defense Phase 5', 'Best online tailor for Pakistani dresses! The quality exceeded my expectations and the customer service was excellent.', 'https://i.postimg.cc/7GvpWCZM/Whats-App-Image-2025-06-18-at-4-53-33-PM.jpg', 5, 3),
('Nadia from KAECHS', 'Perfect stitching and beautiful finishing! MA Tailor delivered exactly what I wanted. The dress fits like a dream.', 'https://i.postimg.cc/S2WwFyX0/Whats-App-Image-2025-06-18-at-4-53-33-PM-1.jpg', 5, 4),
('Zara from Defense Phase 2', 'Outstanding craftsmanship! The embroidery work on my dress was flawless. Delivery within promised time frame.', NULL, 5, 5),
('Mariam from Falcon Faisal', 'Incredible attention to detail and perfect measurements. MA Tailor is my go-to for all Pakistani formal wear.', NULL, 5, 6),
('Hina from Defense Phase 6', 'Superb quality and excellent customer service. The dress was exactly as shown in the picture. Very satisfied!', NULL, 5, 7),
('Aliya from Defense Phase 7', 'Amazing stitching quality and timely delivery. The dress fits perfectly and looks absolutely beautiful.', NULL, 5, 8),
('Kiran from Defense Phase 8', 'Best online tailor experience! Professional service, quality fabric, and excellent finishing work.', NULL, 5, 9);
